    ./Invoke-Bumper.ps1 -VersionPath version.txt -CommitLogPath commits.txt
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string] $VersionPath,
    [Parameter(Mandatory)][string] $CommitLogPath,
    [string] $ChangelogPath = 'CHANGELOG.md'
)

